$sql = "
CREATE TABLE IF NOT EXISTS " . TABLE_ZONES_TO_POST_CODE_US . " (
    post_zone_id int NOT NULL AUTO_INCREMENT,
    zone_country_id int NOT NULL,
    zone_id int NOT NULL DEFAULT '0',
    post_code varchar(32) NOT NULL,
    zone_name varchar(32) NOT NULL,
    zone_city_name varchar(32) NOT NULL,
    PRIMARY KEY (post_zone_id),
    UNIQUE KEY post_code_2 (post_code,zone_name,zone_city_name),
    KEY zone_name (zone_name),
    KEY zone_id (zone_id)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
";
$this->executeInstallerSql($sql);

